-- Best Infissi: riordino dei collegamenti e schede di linea. Prezzi e opzioni intatti.
-- Validata sulla copia locale completa; la transazione verifica la conservazione di prezzi e opzioni.
do $migrazione$
declare
 p jsonb := $piano${"companyId":"421f4929-04bc-406d-b0fd-3ff4d57a64ee","serramenti":{"id":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","company_id":"421f4929-04bc-406d-b0fd-3ff4d57a64ee","nome":"Serramenti","sort_order":0,"attivo":true,"tipologia":"serramenti","categoria_tipo":"principale","verticali_abilitati":["serramentista"]},"modelli":[{"macroId":"a1405c07-659d-45a5-bd00-584f0e4f6ed0","categoriaId":"ea8b904e-0ca2-5311-aa7f-9a26fdcbaf19","nome":"4Stars"},{"macroId":"5066bc5e-0bc7-4826-8c27-dd81e014767d","categoriaId":"73fca733-98c7-56b1-aa36-274d4d1984bd","nome":"Epiq"},{"macroId":"2fffb7ed-e5ee-457d-9de0-f950b23eff0e","categoriaId":"c06dfb48-c72b-5349-a667-73e769c59a17","nome":"Arrogance"},{"macroId":"27fce4ed-2e45-4834-8348-0973a49a0089","categoriaId":"a13ae05d-2edd-527a-a8ef-d8a8ba22fdac","nome":"5Stars"},{"macroId":"f23795ea-5821-4259-b854-61c59360f817","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174","nome":"Legno-Alluminio"},{"macroId":"8db9814d-c202-42a0-922c-c24272d633c6","categoriaId":"577911fe-932e-5907-ad26-34f70dac3e48","nome":"Agreen Home"}],"assegnazioni":{"12c6f509-ed86-4ffc-a054-e23a7356573e":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"21f7d8d2-fb32-4ce3-9987-458eb7c17c67":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"25832e82-b53c-498c-ad5e-6c33deaeba6a":{"macroId":"0794e8b8-ce84-4512-8e0a-f6c3cfc4ed52","categoriaId":"26c2fb9d-1813-57d5-a82d-9928158571af"},"370248cc-2b61-46a4-9457-6b96ea6b3f1c":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"4922bdc7-159e-47b8-9215-d2fe64c05a73":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"4d928c75-6e0a-483d-97be-d84b9096dcbd":{"macroId":"0794e8b8-ce84-4512-8e0a-f6c3cfc4ed52","categoriaId":"26c2fb9d-1813-57d5-a82d-9928158571af"},"4e69cf2f-b2fb-4f17-9c7a-9d7e96bd794c":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"549b02bd-bd0e-4d8a-aaf5-f5e8d158787c":{"macroId":"7274d7ac-080c-5ab3-af0b-e8d7e606e4ec","categoriaId":"68678eea-e5f6-5579-a286-1901c566d174"},"625170c2-4cbf-4437-9c70-ff2c4a4bfa4f":{"macroId":"ba4bd482-1a9e-40a4-b087-99b07df58bdd","categoriaId":"ef6255dc-b816-5351-adf3-f07c3055cc11"},"9b5e3fef-f24c-4078-8299-9beef0fd5d20":{"macroId":"f26be55d-f8b7-4858-96c6-cb611600c6b3","categoriaId":"36075f6b-912e-5f21-a159-b14756f1d9c3"},"d58faa4d-4b69-4b82-944d-202ea42b6570":{"macroId":"6fa09972-6ce8-466d-8f77-fa9df076add0","categoriaId":"dbd17fad-2928-55a5-abf2-3c330719d482"},"df09a15e-c269-43d1-b8dc-baddcfa5f703":{"macroId":"ba4bd482-1a9e-40a4-b087-99b07df58bdd","categoriaId":"ef6255dc-b816-5351-adf3-f07c3055cc11"}},"categorieAggiuntive":[{"id":"26c2fb9d-1813-57d5-a82d-9928158571af","nome":"Import Agreen Home · prezzi da verificare","macrocategoria_id":"0794e8b8-ce84-4512-8e0a-f6c3cfc4ed52","sort_order":100},{"id":"ef6255dc-b816-5351-adf3-f07c3055cc11","nome":"Import Agreen Home · prezzi da verificare","macrocategoria_id":"ba4bd482-1a9e-40a4-b087-99b07df58bdd","sort_order":100},{"id":"36075f6b-912e-5f21-a159-b14756f1d9c3","nome":"Import Agreen Home · prezzi da verificare","macrocategoria_id":"f26be55d-f8b7-4858-96c6-cb611600c6b3","sort_order":100},{"id":"dbd17fad-2928-55a5-abf2-3c330719d482","nome":"Import Agreen Home · prezzi da verificare","macrocategoria_id":"6fa09972-6ce8-466d-8f77-fa9df076add0","sort_order":100}],"scriviModelloInDescrizione":true}$piano$::jsonb;
 schede jsonb := $schede$[{"id":"ea8b904e-0ca2-5311-aa7f-9a26fdcbaf19","nome":"4Stars","chiave":"4stars","produttore":"QFORT","url":"https://qfort.it/finestre/finestre-pvc/4stars/","foto":"https://qfort.it/wp-content/uploads/2025/07/4Stars-PVC-interno-chiuso.webp","descrizione":"Sistema in PVC con profili a cinque camere, pensato per dare luce agli ambienti e migliorare il comfort della casa. Consente finiture interne ed esterne diverse e rivestimento esterno Alu-Clips.","dati":["Profondità 70 mm","5 camere","Vetrocamera 24–40 mm"],"personalizzazioni":["Bicolore interno/esterno e Alu-Clips","Vetri e ferramenta secondo configurazione","Forme ad arco, cerchio, trapezio e triangolo su richiesta"],"attenzione":"Le forme speciali richiedono disegno e conferma tecnica. Gli scorrevoli appartengono alle gamme Paysage: non tutti i sistemi scorrevoli del vecchio listino sono confermati per 4Stars."},{"id":"73fca733-98c7-56b1-aa36-274d4d1984bd","nome":"Epiq 6Stars","chiave":"epiq","produttore":"QFORT","url":"https://qfort.it/finestre/finestre-pvc/epiq-6stars/","foto":"https://qfort.it/wp-content/uploads/2025/07/QFORT-Finstra-Epiq.webp","descrizione":"Finestra in PVC dalle linee sottili, disponibile con anta dritta o complanare. Il profilo a sei camere e le tre guarnizioni aiutano l’isolamento, mentre il nodo ridotto favorisce la luce naturale.","dati":["Profondità 76 mm","6 camere","3 guarnizioni","Vetrocamera 44 mm"],"personalizzazioni":["Anta dritta o complanare","Bicolore e rivestimento Alu-Clips","Triplo vetro con canalina calda"],"profilo":["Anta dritta","Anta complanare"],"attenzione":"La scheda ufficiale riporta triplo vetro da 44 mm. “Standard / Antisonoro / Antisfondamento” non specifica la composizione. Per gli scorrevoli verificare la gamma Traslante Epiq."},{"id":"c06dfb48-c72b-5349-a667-73e769c59a17","nome":"Arrogance","chiave":"arrogance","produttore":"QFORT","url":"https://qfort.it/finestre/finestre-alluminio/arrogance/","foto":"https://qfort.it/wp-content/uploads/2025/07/QFORT-Finstra-Arrogance-alluminio.webp","descrizione":"Sistema in alluminio dal profilo essenziale e squadrato, progettato per privilegiare la superficie vetrata. La barriera termica e la guarnizione mediana contribuiscono al comfort degli ambienti.","dati":["Profondità 65 mm","Vetrocamera 24–40 mm"],"personalizzazioni":["Doppia colorazione interno/esterno","Cerniere a scomparsa: configurazioni 95° / 180° da confermare","Colori strutturati e opachi"],"attenzione":"La finestra Arrogance e lo scorrevole Arrogance sono sistemi distinti: profondità, vetri e limiti della finestra non vanno applicati allo scorrevole."},{"id":"a13ae05d-2edd-527a-a8ef-d8a8ba22fdac","nome":"5Stars Alluminio","chiave":"5stars","produttore":"QFORT","url":"https://qfort.it/finestre/finestre-alluminio/5stars/","foto":"https://qfort.it/wp-content/uploads/2025/07/5Stars-AL-interno-chiuso.webp","descrizione":"Serramento in alluminio a taglio termico dalle linee squadrate. Disponibile con doppio o triplo vetro, colori interni ed esterni differenti e possibilità di cerniere nascoste.","dati":["Profondità 70 mm","2 guarnizioni","Vetrocamera 24–50 mm"],"personalizzazioni":["Doppio o triplo vetro","Bicolore interno/esterno","Cerniere a scomparsa"],"attenzione":"Questo modello del listino è 5Stars in alluminio. Non va confuso con 5Stars PVC, 5Stars Invisible o Paysage 5Stars."},{"id":"68678eea-e5f6-5579-a286-1901c566d174","nome":"Legno-Alluminio","chiave":"legno_alluminio","produttore":"Da identificare per i 23 articoli generici","url":"https://www.portefinestreanger.it/prodotti/infissi-in-legno-alluminio/","foto":null,"descrizione":"Il gruppo contiene 23 tipologie generiche senza una serie produttore identificata e sei articoli AnGer: Social, Mini Social e Social Plus. Le schede AnGer valgono per gli articoli che riportano espressamente il modello.","dati":[],"personalizzazioni":["Essenze, finiture, profili e ferramenta secondo la singola serie"],"attenzione":"Non attribuire automaticamente i 23 serramenti generici a QFORT o a una specifica serie AnGer."},{"id":"577911fe-932e-5907-ad26-34f70dac3e48","nome":"Home","chiave":"agreen_home","produttore":"Agreen","url":"https://www.agreenfinestre.com/it/agreen-home/","foto":"https://www.agreenfinestre.com/wp-content/uploads/agreen-serramenti-finestre-ambiente-2024-17-696x1024.jpg","descrizione":"Sistema in PVC con rinforzo in acciaio e due guarnizioni. Offre telai, ante e fermavetri con forme diverse, finiture in PVC e rivestimenti in alluminio.","dati":["Telaio 70 mm","Anta 70–78 mm","5 camere","Vetro 22–41 mm"],"personalizzazioni":["Finestre e portefinestre 1 / 2 ante","Fisso e vasistas","Scorrevole parallelo: anta mobile + fisso","Bianco massa 159P / Avorio massa 9001P e altre finiture"],"attenzione":"Agreen Home non è QFORT. Home Lift and Slide e Slinova Slide sono gamme separate. Tre ante, alzanti, Smart Slide e portoncini del listino richiedono conferma del fornitore."}]$schede$::jsonb;
 azienda uuid := (p->>'companyId')::uuid;
 gruppo uuid := (p->'serramenti'->>'id')::uuid;
 m jsonb; s jsonb; a record;
 prima jsonb; dopo jsonb; opzioni_prima text; opzioni_dopo text;
begin
 if not exists(select 1 from public.companies where id=azienda) then return; end if;
 if not exists(select 1 from public.article_families where company_id=azienda and deleted_at is null) then return; end if;
 perform 1 from public.article_families where company_id=azienda for update;
 if exists(select 1 from jsonb_array_elements(p->'modelli') x where not exists(select 1 from public.listino_macrocategorie where id=(x->>'macroId')::uuid and company_id=azienda)) then
  raise exception 'Catalogo Best Infissi diverso da quello verificato: riordino interrotto.';
 end if;
 select jsonb_agg(to_jsonb(f)-array['macrocategoria_id','categoria_id','descrizione','updated_at','embedding','embedding_updated_at'] order by id) into prima from public.article_families f where company_id=azienda;
 select md5(jsonb_build_array(
  (select jsonb_agg(to_jsonb(x) order by id) from public.article_family_axes x where company_id=azienda),
  (select jsonb_agg(to_jsonb(x) order by id) from public.article_family_axis_values x where company_id=azienda),
  (select jsonb_agg(to_jsonb(x) order by id) from public.listino_griglia x where company_id=azienda))::text) into opzioni_prima;
 if exists(select 1 from public.listino_macrocategorie where id=gruppo and company_id<>azienda) then raise exception 'ID gruppo già usato da un’altra azienda.'; end if;
 insert into public.listino_macrocategorie(id,company_id,nome,sort_order,attivo,tipologia,categoria_tipo,verticali_abilitati)
 values(gruppo,azienda,'Serramenti',0,true,'serramenti','principale',array['serramentista']) on conflict(id) do nothing;
 for m in select value from jsonb_array_elements(p->'modelli') loop
  if exists(select 1 from public.listino_categorie where id=(m->>'categoriaId')::uuid and (company_id<>azienda or macrocategoria_id is distinct from gruppo or nome<>m->>'nome')) then raise exception 'Categoria modello già usata: riordino interrotto.'; end if;
  insert into public.listino_categorie(id,company_id,nome,macrocategoria_id,sort_order)
  values((m->>'categoriaId')::uuid,azienda,m->>'nome',gruppo,10*(select ordinality-1 from jsonb_array_elements(p->'modelli') with ordinality x(value,ordinality) where x.value->>'nome'=m->>'nome')) on conflict(id) do nothing;
  update public.article_families set macrocategoria_id=gruppo,categoria_id=(m->>'categoriaId')::uuid
   where company_id=azienda and deleted_at is null and macrocategoria_id=(m->>'macroId')::uuid;
 end loop;
 for m in select value from jsonb_array_elements(p->'categorieAggiuntive') loop
  if not exists(select 1 from public.listino_macrocategorie where id=(m->>'macrocategoria_id')::uuid and company_id=azienda) then raise exception 'Gruppo accessori non trovato.'; end if;
  if exists(select 1 from public.listino_categorie where id=(m->>'id')::uuid and company_id<>azienda) then raise exception 'Categoria accessori di un’altra azienda.'; end if;
  insert into public.listino_categorie(id,company_id,nome,macrocategoria_id,sort_order)
   values((m->>'id')::uuid,azienda,m->>'nome',(m->>'macrocategoria_id')::uuid,100) on conflict(id) do nothing;
 end loop;
 for a in select key,value from jsonb_each(p->'assegnazioni') loop
  if not exists(select 1 from public.article_families where id=a.key::uuid and company_id=azienda and deleted_at is null) then raise exception 'Articolo da ricollocare non trovato: %',a.key; end if;
  update public.article_families set macrocategoria_id=(a.value->>'macroId')::uuid,categoria_id=(a.value->>'categoriaId')::uuid
   where id=a.key::uuid and company_id=azienda and (macrocategoria_id is distinct from (a.value->>'macroId')::uuid or categoria_id is distinct from (a.value->>'categoriaId')::uuid);
 end loop;
 for m in select value from jsonb_array_elements(p->'modelli') loop
  update public.article_families set descrizione=concat_ws(E'\n',nullif(descrizione,''),'Modello: '||(m->>'nome'))
   where company_id=azienda and categoria_id=(m->>'categoriaId')::uuid and macrocategoria_id=gruppo and deleted_at is null
    and not ('Modello: '||(m->>'nome')=any(string_to_array(coalesce(descrizione,''),E'\n')));
  update public.listino_macrocategorie set attivo=false,tipologia=null,verticali_abilitati=array[]::text[]
   where id=(m->>'macroId')::uuid and company_id=azienda and attivo
    and not exists(select 1 from public.article_families where macrocategoria_id=(m->>'macroId')::uuid and company_id=azienda and deleted_at is null);
 end loop;
 for s in select value from jsonb_array_elements(schede) loop
  if exists(select 1 from public.listino_schede_linea where id=(s->>'id')::uuid and company_id<>azienda) then raise exception 'Scheda appartenente a un’altra azienda.'; end if;
  insert into public.listino_schede_linea(id,company_id,macrocategoria_id,chiave,nome,descrizione,immagine_url,scheda_tecnica_url,scheda_tecnica_nome)
   values((s->>'id')::uuid,azienda,gruppo,s->>'chiave',s->>'nome',concat_ws(E'\n\n',s->>'descrizione',s->>'attenzione'),s->>'foto',s->>'url','Sito ufficiale del produttore') on conflict(id) do nothing;
 end loop;
 select jsonb_agg(to_jsonb(f)-array['macrocategoria_id','categoria_id','descrizione','updated_at','embedding','embedding_updated_at'] order by id) into dopo from public.article_families f where company_id=azienda;
 select md5(jsonb_build_array(
  (select jsonb_agg(to_jsonb(x) order by id) from public.article_family_axes x where company_id=azienda),
  (select jsonb_agg(to_jsonb(x) order by id) from public.article_family_axis_values x where company_id=azienda),
  (select jsonb_agg(to_jsonb(x) order by id) from public.listino_griglia x where company_id=azienda))::text) into opzioni_dopo;
 if prima is distinct from dopo or opzioni_prima is distinct from opzioni_dopo then raise exception 'Dati economici o opzioni modificati: transazione annullata.'; end if;
end;
$migrazione$;
